def tokenize(texts):
    enc = tokenizer(texts, return_tensors="pt", padding=True)
    return enc["input_ids"].to(DEVICE), enc["attention_mask"].to(DEVICE)


def collect(texts, erasers=None, layers=(), batch_size=128):
    """Run the model over `texts`, optionally erasing inside the forward pass.

    Returns (activations at each layer in `layers`, stacked over every non-pad
    token position; final-token logits for every sequence)."""
    acts = {l: [] for l in layers}
    last_logits = []
    modules = [blocks[l] for l in layers]

    for start in range(0, len(texts), batch_size):
        input_ids, attn_mask = tokenize(texts[start:start + batch_size])

        with torch.no_grad(), model.trace(input_ids, attention_mask=attn_mask) as tracer:
            # Declared first, but it observes post-intervention values.
            cache = tracer.cache(modules=modules, device=torch.device("cpu"),
                                 dtype=torch.float32) if modules else None
            if erasers:
                apply_erasure(erasers)              # defined in Step 3
            logits = model.lm_head.output.save()

        keep = attn_mask.cpu().bool()
        for l in layers:
            acts[l].append(cache[f"model.transformer.h.{l}"].output[keep].half())
        lengths = keep.sum(1)
        last_logits.append(logits[torch.arange(len(lengths)), lengths - 1].float().cpu())

    return {l: torch.cat(v) for l, v in acts.items()}, torch.cat(last_logits)

def position_index(texts, batch_size=128):
    seq_of_row, is_last_row = [], []
    for start in range(0, len(texts), batch_size):
        _, attn_mask = tokenize(texts[start:start + batch_size])
        for b, length in enumerate(attn_mask.sum(1).cpu().numpy()):
            seq_of_row += [start + b] * length
            is_last_row += [p == length - 1 for p in range(length)]
    return np.array(seq_of_row), np.array(is_last_row)

