def to_device(spec):
    return {s: (M.float().to(DEVICE), mu.float().to(DEVICE)) for s, (M, mu) in spec.items()}

def leace_erasers(sites):
    return to_device({s: leace[s] for s in sites})

def inlp_erasers(k, sites):
